(()=> {
const $=id=>document.getElementById(id);
const state={user:null,pendingAvatarUrl:null,mode:'login',view:'feed',feedType:'new',socket:null,upload:null,activeChat:null,chats:[],activeServer:null,activeServerChannel:null,voiceStream:null,voicePeers:{},voiceChatOpen:false};
const api=async(url,opts={})=>{const res=await fetch(url,{credentials:'same-origin',...opts,headers:{...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opts.headers||{})}});const d=await res.json().catch(()=>({error:'Некорректный ответ сервера'}));if(!res.ok)throw new Error(d.error||'Ошибка запроса');return d};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=m=>{const t=$('toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)};
const avatar=(emoji,url)=>`<div class="avatar">${url?`<img src="${esc(url)}" alt="">`:esc(emoji||'👤')}</div>`;
const dt=d=>d?new Date(d).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'сейчас';
function setAuthMode(mode){state.mode=mode;const reg=mode==='register';$('authTitle').textContent=reg?'Создай аккаунт':'С возвращением';$('authHint').textContent=reg?'Зарегистрируйся и найди своих':'Войди, чтобы продолжить общение';$('displayNameWrap').classList.toggle('hidden',!reg);$('usernameWrap').classList.toggle('hidden',!reg);$('loginLabel').textContent=reg?'Электронная почта':'Почта или юзернейм';$('login').placeholder=reg?'name@example.com':'name@example.com или username';$('login').type=reg?'email':'text';$('authSubmit').innerHTML=reg?'Создать аккаунт <span>→</span>':'Войти в NEXUS <span>→</span>';$('authSwitchText').textContent=reg?'Уже есть аккаунт?':'Нет аккаунта?';$('switchAuth').textContent=reg?'Войти':'Зарегистрироваться';$('authError').textContent=''}
$('switchAuth').onclick=()=>setAuthMode(state.mode==='login'?'register':'login');
$('authForm').onsubmit=async e=>{e.preventDefault();$('authSubmit').disabled=true;$('authError').textContent='';try{const reg=state.mode==='register';const data=await api('/api/auth/'+(reg?'register':'login'),{method:'POST',body:JSON.stringify(reg?{email:$('login').value.trim(),username:$('username').value.trim(),displayName:$('displayName').value.trim(),password:$('password').value}:{login:$('login').value.trim(),password:$('password').value})});state.user=data.user;afterLogin();toast(reg?'Аккаунт создан':'Добро пожаловать!')}catch(e){$('authError').textContent=e.message==='Failed to fetch'?'Сервер недоступен. Запусти backend по инструкции README.':e.message}finally{$('authSubmit').disabled=false}};
$('logoutBtn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}if(state.socket)state.socket.disconnect();state.user=null;$('authScreen').classList.remove('hidden');$('viewRoot').classList.add('hidden');$('logoutBtn').classList.add('hidden');toast('Ты вышел из аккаунта')};
$('themeBtn').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('nexusTheme',document.body.classList.contains('light')?'light':'dark')};
if(localStorage.getItem('nexusTheme')==='light'){document.body.classList.add('light');document.documentElement.dataset.theme='light'}else{document.documentElement.dataset.theme='dark'};if(localStorage.getItem('nexusChatWallpaperImage'))document.body.style.setProperty('--chat-wallpaper',`url("${localStorage.getItem('nexusChatWallpaperImage')}")`);
$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){go('people').then(()=>{const q=$('peopleSearch');if(q){q.value=$('globalSearch').value; q.dispatchEvent(new Event('input'))}})}});$('topAvatar').onclick=()=>go('profile');
$('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view)});
document.querySelector('.brand').onclick=e=>{e.preventDefault();go('feed')};
function afterLogin(){ $('authScreen').classList.add('hidden');$('viewRoot').classList.remove('hidden');$('miniName').textContent=state.user.displayName;$('miniHandle').textContent='@'+state.user.username;$('miniAvatar').innerHTML=state.user.avatarUrl?`<img src="${esc(state.user.avatarUrl)}">`:'';$('topAvatar').innerHTML=state.user.avatarUrl?`<img src="${esc(state.user.avatarUrl)}">`:'';$('logoutBtn').classList.remove('hidden');if(typeof io==='function'){state.socket=io();state.socket.on('chat:message',()=>{if(state.view==='messages')renderMessages()});state.socket.on('chat:read',()=>{if(state.view==='messages')renderMessages()})}go('messages')}
const titles={feed:'Лента',shorts:'Shorts',videos:'Видео',people:'Поиск',messages:'Чаты',voice:'Голосовые комнаты',servers:'Серверы',profile:'Профиль',settings:'Настройки',admin:'Админ-панель'};
async function go(view){state.view=view;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('pageTitle').textContent=titles[view]||'NEXUS';if(!state.user){$('authScreen').classList.remove('hidden');$('viewRoot').classList.add('hidden');return} $('viewRoot').classList.remove('hidden');$('viewRoot').innerHTML='<div class="empty-state">Загружаем…</div>';try{if(view==='feed'||view==='videos'||view==='shorts')await renderFeed(view);else if(view==='people')await renderPeople();else if(view==='profile')await renderProfile(state.user.username,true);else if(view==='messages')await renderChats();else if(view==='clans'||view==='servers')await renderClans();else if(view==='settings')renderSettings();else if(view==='admin')await renderAdmin();else if(['shorts','voice','stories'].includes(view))renderComingSoon(view)}catch(e){$('viewRoot').innerHTML=`<div class="empty-state">${esc(e.message)}<br><br><button class="secondary" onclick="location.reload()">Обновить</button></div>`}}

async function renderFeed(view){
 const type=view==='videos'?'videos':view==='shorts'?'shorts':state.feedType;
 const d=await api('/api/feed?type='+type);
 const heading=view==='videos'?'Длинные видео':view==='shorts'?'Shorts':'Лента';
 $('viewRoot').innerHTML=`<div class="column"><div class="section-title"><div><h2>${heading}</h2><p class="muted">${view==='videos'?'Видео от 5 минут до 24 часов':view==='shorts'?'Короткие видео от 5 секунд до 5 минут':'Фото и публикации сообщества'}</p></div></div>${view==='feed'?'<div class="tabs"><button class="tab '+(state.feedType==='new'?'active':'')+'" data-feed="new">Публикации</button><button class="tab '+(state.feedType==='recommend'?'active':'')+'" data-feed="recommend">Рекомендации</button><button class="tab '+(state.feedType==='following'?'active':'')+'" data-feed="following">Подписки</button></div>':''}<div id="posts"></div></div>`;
 const list=$('posts');list.innerHTML=d.posts.length?d.posts.map(postHTML).join(''):'<div class="empty-state">Пока здесь нет публикаций.</div>';wirePosts(list);
 if(view==='feed')document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{state.feedType=b.dataset.feed;renderFeed('feed')});
}
function postHTML(p){const media=p.mediaUrl?((p.mediaType==='video'||p.mediaType==='short')?`<video controls playsinline preload="metadata" src="${esc(p.mediaUrl)}"></video>`:`<img loading="lazy" src="${esc(p.mediaUrl)}" alt="Медиа публикации">`):'';return `<article class="post-card" data-post="${p.id}"><div class="post-head"><button class="profile-avatar-link" data-user="${esc(p.username)}">${avatar(p.avatar,p.avatarUrl)}</button><div class="post-author"><b class="click-user" data-user="${esc(p.username)}">${esc(p.displayName)}</b><small>@${esc(p.username)} · ${dt(p.createdAt)}</small></div><button class="more-btn" data-report="${p.id}" title="Пожаловаться">•••</button></div><p class="post-text">${esc(p.body).replace(/(#[A-Za-zА-Яа-я0-9_]+)/g,'<span class="tag-inline">$1</span>')}</p>${media?`<div class="post-media">${media}</div>`:''}<div class="post-stats"><span>♥ ${p.likes} отметок</span><span>${p.comments} комментариев · ${p.reposts} репостов</span></div><div class="post-actions"><button class="action ${p.liked?'active':''}" data-like="${p.id}">♥ Нравится</button><button class="action" data-comments="${p.id}">▢ Комментировать</button><button class="action" data-repost="${p.id}">↗ Репост</button><button class="action ${p.bookmarked?'active':''}" data-save="${p.id}">☆ Сохранить</button>${String(p.userId)===String(state.user.id)?`<button class="action" data-delete="${p.id}">Удалить</button>`:''}</div><div class="comment-area hidden" id="comments-${p.id}"><div class="comment-list"></div><form class="comment-row" data-comment-form="${p.id}"><input class="comment-input" maxlength="1500" placeholder="Написать комментарий…" required><button class="primary small-btn">Отправить</button></form></div></article>`}
async function refreshCurrentView(){if(state.view==='profile')return renderProfile(state.profileUsername||state.user.username,!!state.profileOwn);return renderFeed(state.view==='videos'?'videos':state.view==='shorts'?'shorts':'feed')}
function wirePosts(root){root.querySelectorAll('[data-like]').forEach(b=>b.onclick=async()=>{try{await api(`/api/posts/${b.dataset.like}/like`,{method:'POST',body:'{}'});await refreshCurrentView()}catch(e){toast(e.message)}});root.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{try{await api(`/api/posts/${b.dataset.save}/bookmark`,{method:'POST',body:'{}'});toast('Избранное обновлено');await refreshCurrentView()}catch(e){toast(e.message)}});root.querySelectorAll('[data-repost]').forEach(b=>b.onclick=async()=>{try{await api(`/api/posts/${b.dataset.repost}/repost`,{method:'POST',body:'{}'});toast('Репост добавлен');await refreshCurrentView()}catch(e){toast(e.message)}});root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить публикацию?'))return;try{await api(`/api/posts/${b.dataset.delete}`,{method:'DELETE'});await refreshCurrentView()}catch(e){toast(e.message)}});root.querySelectorAll('[data-comments]').forEach(b=>b.onclick=async()=>{const area=$('comments-'+b.dataset.comments);area.classList.toggle('hidden');if(!area.classList.contains('hidden')){const d=await api(`/api/posts/${b.dataset.comments}/comments`);area.querySelector('.comment-list').innerHTML=d.comments.map(c=>`<div class="comment-item"><b>@${esc(c.username)}</b> ${esc(c.body)}</div>`).join('')||'<small>Пока нет комментариев.</small>'}});root.querySelectorAll('[data-comment-form]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const input=f.querySelector('input');try{await api(`/api/posts/${f.dataset.commentForm}/comments`,{method:'POST',body:JSON.stringify({body:input.value})});await refreshCurrentView()}catch(e){toast(e.message)}});root.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>renderProfile(b.dataset.user,false));root.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{const reason=prompt('Причина жалобы:');if(!reason)return;try{await api('/api/reports',{method:'POST',body:JSON.stringify({postId:b.dataset.report,reason})});toast('Жалоба отправлена модерации')}catch(e){toast(e.message)}})}
async function publishPost(e){e.preventDefault();const body=$('postBody').value.trim();let mediaUrl=null,mediaType=null;try{if(state.upload){const fd=new FormData();fd.append('file',state.upload);const up=await api('/api/upload',{method:'POST',body:fd});mediaUrl=up.url;mediaType=up.type}await api('/api/posts',{method:'POST',body:JSON.stringify({body,mediaUrl,mediaType})});state.upload=null;toast('Публикация опубликована');await renderFeed('feed')}catch(e){toast(e.message)}}
async function searchTag(tag){state.feedType='new';await go('feed');const inp=document.createElement('input');inp.className='search-input';inp.placeholder='Поиск по тексту и хештегам';inp.value='#'+tag;const root=$('viewRoot');root.querySelector('.tabs').after(inp);inp.onkeydown=async e=>{if(e.key==='Enter'){const d=await api('/api/feed?type=new&q='+encodeURIComponent(inp.value));$('posts').innerHTML=d.posts.map(postHTML).join('')||'<div class="empty-state">Публикаций не найдено</div>';wirePosts($('posts'))}}}
async function renderPeople(){const d=await api('/api/users/search?q=');$('viewRoot').innerHTML=`<div class="card"><div class="section-title"><div><h2>Найти людей</h2><p class="muted">Ищи по юзернейму или имени</p></div></div><input id="peopleSearch" class="search-input" placeholder="Например, @alex"><div id="peopleResults" style="margin-top:12px"></div></div>`;const search=async()=>{const q=$('peopleSearch').value.trim();if(!q){$('peopleResults').innerHTML='<div class="empty-state">Начни вводить имя или юзернейм.</div>';return}const d=await api('/api/users/search?q='+encodeURIComponent(q));$('peopleResults').innerHTML=d.users.map(u=>`<div class="user-result"><button class="profile-avatar-link" data-profile="${esc(u.username)}">${avatar(u.avatar,u.avatarUrl)}</button><div class="result-info"><b class="click-user" data-profile="${esc(u.username)}">${esc(u.displayName)}</b><small>@${esc(u.username)} · ${esc(u.bio||'Без описания')}</small></div><button class="secondary small-btn" data-profile="${esc(u.username)}">Профиль</button><button class="primary small-btn" data-follow="${u.id}">${u.following?'Отписаться':'Подписаться'}</button></div>`).join('')||'<div class="empty-state">Пользователи не найдены.</div>';document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>renderProfile(b.dataset.profile,false));document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=async()=>{await api('/api/users/'+b.dataset.follow+'/follow',{method:'POST',body:'{}'});search()})};$('peopleSearch').oninput=()=>{clearTimeout(search.timer);search.timer=setTimeout(search,180)}}
async function renderProfile(username,own){
 state.profileUsername=username;state.profileOwn=own;
 const d=await api('/api/users/'+encodeURIComponent(username));const u=d.user;
 const feed=await api('/api/feed?type=new');const posts=feed.posts.filter(p=>String(p.userId)===String(u.id));
 const likes=posts.reduce((sum,p)=>sum+(Number(p.likes)||0),0);
 const active=state.profileTab||'posts';
 let content='';
 if(active==='posts')content=posts.map(postHTML).join('')||'<div class="empty-state">Публикаций пока нет.</div>';
 else if(!own)content='<div class="empty-state">Этот раздел доступен только владельцу профиля.</div>';
 else if(active==='drafts'){
  const drafts=JSON.parse(localStorage.getItem('nexusDrafts:'+state.user.id)||'[]');
  content=drafts.map((x,i)=>`<div class="card draft-row"><div><b>${esc(x.body||x.fileName||'Черновик без текста')}</b><small class="muted">${dt(x.createdAt)}${x.fileName?' · '+esc(x.fileName):''}</small></div><button class="secondary small-btn" data-draft-delete="${i}">Удалить</button></div>`).join('')||'<div class="empty-state">Черновиков пока нет.</div>';
 }else{
  const type=({reposts:'reposts',liked:'liked',saved:'saved'})[active];
  const result=await api('/api/feed?type='+type);content=result.posts.map(postHTML).join('')||'<div class="empty-state">Здесь пока ничего нет.</div>';
 }
 const tabs=[['posts','Публикации'],['drafts','Черновики'],['reposts','Репосты'],['liked','Понравилось'],['saved','Избранное']];
 $('viewRoot').innerHTML=`<div class="column"><div class="card profile-card">
 <div class="profile-cover vk-profile-cover" ${u.bannerUrl?`style="background-image:url('${esc(u.bannerUrl)}');background-size:cover;background-position:center"`:''}></div>
 <div class="profile-head"><div class="profile-avatar-wrap">${avatar(u.avatar,u.avatarUrl)}${own?'<button class="profile-story-plus" id="profileStoryPlus" title="Добавить историю">＋</button>':''}</div>
 <div class="profile-names"><h2>${esc(u.displayName)} ${u.role==='admin'?'♛':''}</h2><small>@${esc(u.username)} · ID ${u.id}</small></div>
 ${own?'<button class="secondary" id="editProfileBtn">Изменить профиль</button>':`<button class="primary" id="followProfile">${u.isFollowing?'Отписаться':'Подписаться'}</button><button class="secondary" id="messageProfile">Написать</button>`}</div>
 <div class="profile-bio">${esc(u.bio||'Пользователь пока ничего не рассказал о себе.')}</div>
 <div class="stat-grid"><div class="stat-box"><b>${likes}</b><small>Лайки</small></div><div class="stat-box"><b>${u.followers}</b><small>Подписчики</small></div><div class="stat-box"><b>${u.followingCount}</b><small>Подписки</small></div></div>
 </div><div class="tabs profile-tabs">${tabs.map(([id,label])=>`<button class="tab ${active===id?'active':''}" data-profile-tab="${id}">${label}</button>`).join('')}</div>
 ${own&&active==='posts'?'<div class="profile-publish-row"><button class="primary" id="profilePublish">＋ Опубликовать фото / видео</button></div>':''}
 <div id="profilePosts">${content}</div></div>`;
 wirePosts($('profilePosts'));
 document.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{state.profileTab=b.dataset.profileTab;renderProfile(username,own)});
 document.querySelectorAll('[data-draft-delete]').forEach(b=>b.onclick=()=>{const key='nexusDrafts:'+state.user.id;const drafts=JSON.parse(localStorage.getItem(key)||'[]');drafts.splice(Number(b.dataset.draftDelete),1);localStorage.setItem(key,JSON.stringify(drafts));renderProfile(username,own)});
 if(own){$('editProfileBtn').onclick=()=>go('settings');$('profileStoryPlus').onclick=createStory;if($('profilePublish'))$('profilePublish').onclick=openProfilePublisher}
 if(!own){$('followProfile').onclick=async()=>{await api('/api/users/'+u.id+'/follow',{method:'POST',body:'{}'});renderProfile(username,false)};$('messageProfile').onclick=async()=>{await api('/api/chats/'+u.id,{method:'POST',body:'{}'});go('messages')}}
}
function openProfilePublisher(){
 const old=document.getElementById('publishModal');if(old)old.remove();
 const modal=document.createElement('div');modal.id='publishModal';modal.className='modal-backdrop';
 modal.innerHTML=`<div class="card publish-modal"><button class="modal-close" id="publishClose">×</button><h2>Новая публикация</h2><p class="muted">Выбери, что хочешь опубликовать. После загрузки останешься в профиле.</p><div class="field"><label>Тип публикации</label><select id="publishKind"><option value="image">Фото — попадёт в ленту</option><option value="short">Shorts — видео 5 секунд – 5 минут</option><option value="video">Видео — от 5 минут до 24 часов</option></select></div><div class="field"><label>Файл</label><input id="publishFile" type="file" accept="image/*"></div><div class="field"><label>Описание</label><textarea id="publishCaption" maxlength="5000" placeholder="Добавь описание…"></textarea></div><div id="publishInfo" class="tiny muted">Для фото выбери изображение.</div><div class="modal-actions"><button class="secondary" id="publishCancel">Отмена</button><button class="primary" id="publishSubmit">Опубликовать</button></div></div>`;
 document.body.append(modal);
 const kind=modal.querySelector('#publishKind'),file=modal.querySelector('#publishFile'),info=modal.querySelector('#publishInfo');
 const update=()=>{file.value='';file.accept=kind.value==='image'?'image/*':'video/mp4,video/webm,video/quicktime';info.textContent=kind.value==='image'?'Только фото. Оно появится в ленте.':kind.value==='short'?'Видео длительностью от 5 секунд до 5 минут.':'Видео длительностью от 5 минут до 24 часов.'};
 kind.onchange=update;const close=()=>modal.remove();modal.querySelector('#publishClose').onclick=close;modal.querySelector('#publishCancel').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};
 file.onchange=()=>{const f=file.files[0];if(!f)return;info.textContent=`${f.name} · ${(f.size/1024/1024).toFixed(1)} МБ`;};
 modal.querySelector('#publishSubmit').onclick=async()=>{
  const f=file.files[0],type=kind.value,body=modal.querySelector('#publishCaption').value.trim();if(!f){toast('Выбери файл');return}
  if(type==='image'&&!f.type.startsWith('image/')){toast('Для ленты выбери фото');return}if(type!=='image'&&!f.type.startsWith('video/')){toast('Выбери видеофайл');return}
  const btn=modal.querySelector('#publishSubmit');btn.disabled=true;btn.textContent='Загрузка…';
  try{
   let duration=0;if(type!=='image'){duration=await readVideoDuration(f);const min=type==='short'?5:300,max=type==='short'?300:86400;if(duration<min||duration>max)throw new Error(type==='short'?'Shorts должны быть от 5 секунд до 5 минут':'Длинное видео должно быть от 5 минут до 24 часов')}
   const fd=new FormData();fd.append('file',f);const up=await api('/api/upload',{method:'POST',body:fd});
   await api('/api/posts',{method:'POST',body:JSON.stringify({body,mediaUrl:up.url,mediaType:type,mediaDuration:Math.round(duration)})});
   toast(type==='image'?'Фото опубликовано в ленте':type==='short'?'Shorts опубликован':'Видео опубликовано');close();state.profileTab='posts';await renderProfile(state.user.username,true);
  }catch(e){toast(e.message)}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Опубликовать'}}
 };
}
function readVideoDuration(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),v=document.createElement('video');v.preload='metadata';v.onloadedmetadata=()=>{const d=v.duration;URL.revokeObjectURL(url);resolve(Number.isFinite(d)?d:0)};v.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Не удалось прочитать длительность видео'))};v.src=url})}
async function createStory(){const fileInput=document.createElement('input');fileInput.type='file';fileInput.accept='image/*,video/mp4,video/webm,video/quicktime';fileInput.onchange=async()=>{const f=fileInput.files[0];if(!f)return;try{const fd=new FormData();fd.append('file',f);const up=await api('/api/upload',{method:'POST',body:fd});const caption=prompt('Подпись к истории (необязательно)','')||'';await api('/api/stories',{method:'POST',body:JSON.stringify({mediaUrl:up.url,mediaType:up.type,caption})});toast('История опубликована на 24 часа');}catch(e){toast(e.message)}};fileInput.click()}
async function renderClans(){const d=await api('/api/clans');$('viewRoot').innerHTML=`<div class="section-title"><div><h2>Серверы</h2><p class="muted">Заходи на серверы или создавай собственные пространства с каналами</p></div><button id="createClan" class="primary">＋ Создать сервер</button></div><div class="grid-cards">${d.clans.map(c=>`<div class="media-card server-card"><div class="server-card-main" data-enter-server="${c.id}"><div class="emoji">${esc(c.emoji)}</div><h2>${esc(c.name)}</h2><p class="muted">#${esc(c.tag)} · ${c.members} участников</p><p>${esc(c.description)}</p><b class="link-btn">${c.joined?'Открыть сервер →':'Вступить и открыть →'}</b></div><button class="secondary" data-join-clan="${c.id}">${c.joined?'Покинуть':'Вступить'}</button></div>`).join('')||'<div class="empty-state">Серверов пока нет. Создай первый!</div>'}</div>`;$('createClan').onclick=async()=>{const name=prompt('Название сервера');if(!name)return;const tag=prompt('Уникальный тег, например GAMING');if(!tag)return;const emoji=prompt('Эмодзи сервера','⚡')||'⚡';const description=prompt('Описание сервера','')||'';try{const r=await api('/api/clans',{method:'POST',body:JSON.stringify({name,tag,emoji,description})});await openServer(r.clan.id)}catch(e){toast(e.message)}};document.querySelectorAll('[data-enter-server]').forEach(el=>el.onclick=async()=>{const id=el.dataset.enterServer;const c=d.clans.find(x=>String(x.id)===String(id));if(!c.joined){await api('/api/clans/'+id+'/join',{method:'POST',body:'{}'})}openServer(id)});document.querySelectorAll('[data-join-clan]').forEach(b=>b.onclick=async()=>{const r=await api('/api/clans/'+b.dataset.joinClan+'/join',{method:'POST',body:'{}'});toast(r.joined?'Ты вступил на сервер':'Ты покинул сервер');renderClans()})}
async function renderEvents(){const d=await api('/api/events');$('viewRoot').innerHTML=`<div class="section-title"><div><h2>События и ивенты</h2><p class="muted">Встречайся с сообществом и собирай награды</p></div></div><div class="column">${d.events.map(e=>`<div class="card event-row"><div class="avatar">🎯</div><div class="result-info"><b>${esc(e.title)}</b><small>${dt(e.starts_at)} · ${e.participants} участников</small><p class="muted">${esc(e.description)}</p></div><button class="primary small-btn" data-join-event="${e.id}">${e.joined?'Не участвую':'Участвовать'}</button></div>`).join('')||'<div class="empty-state">Пока нет активных ивентов.</div>'}</div>`;document.querySelectorAll('[data-join-event]').forEach(b=>b.onclick=async()=>{await api('/api/events/'+b.dataset.joinEvent+'/join',{method:'POST',body:'{}'});renderEvents()})}
async function renderLeaderboard(){const d=await api('/api/leaderboard');$('viewRoot').innerHTML=`<div class="card"><div class="section-title"><div><h2>Рейтинг сообщества</h2><p class="muted">По количеству подписчиков и публикаций</p></div></div>${d.users.map((u,i)=>`<div class="rank-row"><b style="width:28px">#${i+1}</b>${avatar(u.avatar_emoji)}<div class="result-info"><b>${esc(u.display_name)}</b><small>@${esc(u.username)} · ${u.posts} публикаций</small></div><span class="tag">♧ ${u.followers}</span></div>`).join('')}</div>`}
async function renderNotifications(){const d=await api('/api/notifications');await api('/api/notifications/read',{method:'POST',body:'{}'});$('viewRoot').innerHTML=`<div class="card"><div class="section-title"><div><h2>Уведомления</h2><p class="muted">Что нового в твоём NEXUS</p></div><button class="secondary" id="markRead">Прочитано</button></div>${d.notifications.map(n=>`<div class="notice-row ${n.read_at?'':'unread'}">${avatar(n.avatar_emoji)}<div class="result-info"><b>${esc(n.display_name||'Система')} <span class="muted">${esc(n.body)}</span></b><small>${dt(n.created_at)}</small></div></div>`).join('')||'<div class="empty-state">Уведомлений пока нет.</div>'}</div>`;$('markRead').onclick=()=>toast('Уведомления отмечены прочитанными');loadNotificationCount()}
async function loadNotificationCount(){try{const d=await api('/api/notifications');const n=d.notifications.filter(x=>!x.read_at).length;$('notificationCount').textContent=n;$('notificationCount').classList.toggle('hidden',!n)}catch{}}
async function openServer(id){try{const d=await api('/api/clans/'+id+'/space');state.activeServer=d.server;state.activeServer.role=d.role;state.activeServerChannels=d.channels;state.activeServerChannel=null;renderServerSpace()}catch(e){toast(e.message)}}
function renderServerSpace(){const s=state.activeServer,chs=state.activeServerChannels||[];if(!s)return;const text=chs.filter(c=>c.type==='text'),voice=chs.filter(c=>c.type==='voice');$('viewRoot').innerHTML=`<div class="server-space"><aside class="server-channel-sidebar card"><button class="secondary back-servers" id="backServers">← Все серверы</button><div class="server-space-title"><span class="server-emoji">${esc(s.emoji)}</span><div><b>${esc(s.name)}</b><small>#${esc(s.tag)}</small></div></div><div class="channel-group"><div class="channel-group-title">ТЕКСТОВЫЕ КАНАЛЫ ${['owner','admin'].includes(s.role)?'<button data-add-channel="text" title="Добавить текстовый канал">＋</button>':''}</div>${text.map(c=>`<button class="channel-item ${state.activeServerChannel&&String(state.activeServerChannel.id)===String(c.id)?'active':''}" data-channel="${c.id}"># ${esc(c.name)}</button>`).join('')||'<small class="muted">Пока нет каналов</small>'}</div><div class="channel-group"><div class="channel-group-title">ГОЛОСОВЫЕ КАНАЛЫ ${['owner','admin'].includes(s.role)?'<button data-add-channel="voice" title="Добавить голосовой канал">＋</button>':''}</div>${voice.map(c=>`<button class="channel-item ${state.activeServerChannel&&String(state.activeServerChannel.id)===String(c.id)?'active':''}" data-channel="${c.id}">◖ ${esc(c.name)}</button>`).join('')||'<small class="muted">Пока нет каналов</small>'}</div></aside><section class="server-channel-main card" id="serverChannelMain"><div class="chat-placeholder"><div class="logo big-logo">${esc(s.emoji)}</div><h2>${esc(s.name)}</h2><p class="muted">Выбери текстовый или голосовой канал слева.</p></div></section></div>`;$('backServers').onclick=()=>{leaveVoice();go('servers')};document.querySelectorAll('[data-add-channel]').forEach(b=>b.onclick=async()=>{const name=prompt(b.dataset.addChannel==='voice'?'Название голосового канала':'Название текстового канала');if(!name)return;try{await api('/api/clans/'+s.id+'/channels',{method:'POST',body:JSON.stringify({name,type:b.dataset.addChannel})});const d=await api('/api/clans/'+s.id+'/space');state.activeServerChannels=d.channels;renderServerSpace()}catch(e){toast(e.message)}});document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{const c=chs.find(x=>String(x.id)===String(b.dataset.channel));if(c)openServerChannel(c)})}
async function openServerChannel(c){state.socket?.off('server:message');state.socket?.on('server:message',m=>{if(state.activeServerChannel&&String(m.channel_id)===String(state.activeServerChannel.id)){if(state.activeServerChannel.type==='voice')loadVoiceChat(m.channel_id);else loadServerText(m.channel_id)}});if(state.voiceChannel&&String(state.voiceChannel.id)!==String(c.id))leaveVoice();state.activeServerChannel=c;const root=$('serverChannelMain');if(!root)return;if(c.type==='text'){root.innerHTML=`<div class="server-channel-head"><h2># ${esc(c.name)}</h2><small class="muted">Текстовый канал сервера</small></div><div class="server-text-messages" id="serverTextMessages"></div><form class="server-compose" id="serverTextForm"><input id="serverTextInput" maxlength="2000" placeholder="Написать в #${esc(c.name)}…" required><button class="primary">➤</button></form>`;state.socket?.emit('server:text:join',{channelId:c.id});await loadServerText(c.id);$('serverTextForm').onsubmit=async e=>{e.preventDefault();const body=$('serverTextInput').value.trim();if(!body)return;try{await api('/api/server-channels/'+c.id+'/messages',{method:'POST',body:JSON.stringify({body})});$('serverTextInput').value='';await loadServerText(c.id)}catch(err){toast(err.message)}}}else{root.innerHTML=`<div class="voice-room"><div class="server-channel-head"><h2>◖ ${esc(c.name)}</h2><small class="muted">Голосовой канал · общение в реальном времени</small></div><div class="voice-participants" id="voiceParticipants"><div class="voice-empty">Подключаемся к голосовому каналу…</div></div><div class="voice-chat-panel hidden" id="voiceChatPanel"><div class="voice-chat-head"><b>Чат канала #${esc(c.name)}</b><button id="closeVoiceChat">×</button></div><div id="voiceChatMessages" class="server-text-messages"></div><form id="voiceChatForm" class="server-compose"><input id="voiceChatInput" maxlength="2000" placeholder="Сообщение только для этого войса…" required><button class="primary">➤</button></form></div><div class="voice-control-bar"><button id="voiceMic" class="voice-control">🎙 <span>Микрофон</span></button><button id="voiceCamera" class="voice-control">📷 <span>Камера</span></button><button id="voiceScreen" class="voice-control">▣ <span>Экран</span></button><button id="voiceChatToggle" class="voice-control voice-chat-toggle" title="Чат этого голосового канала">▤</button><button id="voiceLeave" class="voice-control danger">Выйти</button></div><div id="voiceMedia" class="voice-media"></div></div>`;await joinVoice(c);}}
async function loadServerText(id){const d=await api('/api/server-channels/'+id+'/messages');const el=$('serverTextMessages');if(!el)return;el.innerHTML=d.messages.map(m=>`<div class="server-message">${avatar(m.avatar_emoji,m.avatar_url)}<div><b>${esc(m.display_name)}</b><small>${dt(m.created_at)}</small><p>${esc(m.body)}</p></div></div>`).join('')||'<div class="empty-state">Пока нет сообщений. Напиши первым!</div>';el.scrollTop=el.scrollHeight}
async function joinVoice(c){if(!state.socket?.connected){toast('Нет соединения с сервером');return}state.voiceChannel=c;state.voicePeers={};state.socket.emit('voice:join',{channelId:c.id},async r=>{if(r?.error){toast(r.error);return}for(const peerId of r.peers||[])await createVoicePeer(peerId,true);renderVoiceMembers();});state.socket.off('voice:peer-joined');state.socket.on('voice:peer-joined',async p=>{toast('Участник подключился к войсу');renderVoiceMembers()});state.socket.off('voice:peer-left');state.socket.on('voice:peer-left',p=>{state.voicePeers[p.peerId]?.close();delete state.voicePeers[p.peerId];renderVoiceMembers()});state.socket.off('voice:signal');state.socket.on('voice:signal',async p=>{let pc=state.voicePeers[p.from];if(!pc)pc=await createVoicePeer(p.from,false);try{if(p.signal.description){await pc.setRemoteDescription(p.signal.description);if(p.signal.description.type==='offer'){await pc.setLocalDescription(await pc.createAnswer());state.socket.emit('voice:signal',{channelId:c.id,to:p.from,signal:{description:pc.localDescription}})}}else if(p.signal.candidate)await pc.addIceCandidate(p.signal.candidate)}catch(e){console.warn(e)}});$('voiceMic').onclick=toggleVoiceMic;$('voiceCamera').onclick=toggleVoiceCamera;$('voiceScreen').onclick=toggleVoiceScreen;$('voiceLeave').onclick=()=>{leaveVoice();renderServerSpace()};$('voiceChatToggle').onclick=()=>toggleVoiceChat(c);}
async function createVoicePeer(peerId,initiator){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});state.voicePeers[peerId]=pc;if(state.voiceStream)state.voiceStream.getTracks().forEach(t=>pc.addTrack(t,state.voiceStream));pc.onicecandidate=e=>{if(e.candidate)state.socket.emit('voice:signal',{channelId:state.voiceChannel.id,to:peerId,signal:{candidate:e.candidate}})};pc.ontrack=e=>{let el=document.getElementById('remote-'+peerId);if(!el){el=document.createElement('video');el.id='remote-'+peerId;el.autoplay=true;el.playsInline=true;el.className='voice-video';$('voiceMedia')?.appendChild(el)}el.srcObject=e.streams[0]};if(initiator){await pc.setLocalDescription(await pc.createOffer());state.socket.emit('voice:signal',{channelId:state.voiceChannel.id,to:peerId,signal:{description:pc.localDescription}})}return pc}
function renderVoiceMembers(){const el=$('voiceParticipants');if(el)el.innerHTML=`<div class="voice-member">${avatar(state.user.avatar,state.user.avatarUrl)}<b>${esc(state.user.displayName)} (ты)</b><small>В голосовом канале</small></div>`}
async function toggleVoiceMic(){try{if(!state.voiceStream)state.voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const t=state.voiceStream.getAudioTracks()[0];t.enabled=!t.enabled;$('voiceMic').classList.toggle('active',t.enabled);$('voiceMic').querySelector('span').textContent=t.enabled?'Микрофон включён':'Микрофон выключен';if(t.enabled)syncVoiceTracks()}catch(e){toast('Не удалось включить микрофон: '+e.message)}}
async function toggleVoiceCamera(){try{if(!state.voiceStream)state.voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});let t=state.voiceStream.getVideoTracks()[0];if(t){t.enabled=!t.enabled}else{const cam=await navigator.mediaDevices.getUserMedia({video:true});t=cam.getVideoTracks()[0];state.voiceStream.addTrack(t);const v=document.createElement('video');v.autoplay=true;v.muted=true;v.playsInline=true;v.className='voice-video';v.srcObject=new MediaStream([t]);$('voiceMedia').appendChild(v)}syncVoiceTracks();$('voiceCamera').classList.toggle('active',t.enabled)}catch(e){toast('Не удалось включить камеру: '+e.message)}}
async function toggleVoiceScreen(){try{const stream=await navigator.mediaDevices.getDisplayMedia({video:true});const track=stream.getVideoTracks()[0];Object.entries(state.voicePeers).forEach(async([peerId,pc])=>{let sender=pc.getSenders().find(x=>x.track?.kind==='video');if(sender)await sender.replaceTrack(track);else{pc.addTrack(track,stream);await pc.setLocalDescription(await pc.createOffer());state.socket.emit('voice:signal',{channelId:state.voiceChannel.id,to:peerId,signal:{description:pc.localDescription}})}});track.onended=()=>{Object.entries(state.voicePeers).forEach(async([peerId,pc])=>{const sender=pc.getSenders().find(x=>x.track?.kind==='video');if(sender)await sender.replaceTrack(state.voiceStream?.getVideoTracks()[0]||null)});$('voiceScreen')?.classList.remove('active')};$('voiceScreen').classList.add('active')}catch(e){toast('Демонстрация экрана отменена или недоступна')}}
function syncVoiceTracks(){Object.entries(state.voicePeers).forEach(async([peerId,pc])=>{let added=false;state.voiceStream?.getTracks().forEach(t=>{const sender=pc.getSenders().find(x=>x.track?.kind===t.kind);if(sender)sender.replaceTrack(t);else{pc.addTrack(t,state.voiceStream);added=true}});if(added){await pc.setLocalDescription(await pc.createOffer());state.socket.emit('voice:signal',{channelId:state.voiceChannel.id,to:peerId,signal:{description:pc.localDescription}})}})}
async function toggleVoiceChat(c){const panel=$('voiceChatPanel');if(!panel)return;panel.classList.toggle('hidden');if(!panel.classList.contains('hidden')){state.socket.emit('server:text:join',{channelId:c.id});await loadVoiceChat(c.id);$('closeVoiceChat').onclick=()=>panel.classList.add('hidden');$('voiceChatForm').onsubmit=async e=>{e.preventDefault();const body=$('voiceChatInput').value.trim();if(!body)return;try{await api('/api/server-channels/'+c.id+'/messages',{method:'POST',body:JSON.stringify({body})});$('voiceChatInput').value='';await loadVoiceChat(c.id)}catch(err){toast(err.message)}}}}
async function loadVoiceChat(id){const d=await api('/api/server-channels/'+id+'/messages');const el=$('voiceChatMessages');if(el)el.innerHTML=d.messages.map(m=>`<div class="server-message">${avatar(m.avatar_emoji,m.avatar_url)}<div><b>${esc(m.display_name)}</b><small>${dt(m.created_at)}</small><p>${esc(m.body)}</p></div></div>`).join('')||'<div class="empty-state">Чат этого войса пока пуст.</div>'}
function leaveVoice(){if(!state.voiceChannel)return;state.socket?.emit('voice:leave');Object.values(state.voicePeers).forEach(p=>p.close());state.voicePeers={};state.voiceStream?.getTracks().forEach(t=>t.stop());state.voiceStream=null;state.voiceChannel=null;state.voiceChatOpen=false}
function renderComingSoon(view){const data={shorts:{icon:'▣',title:'Короткие видео',desc:'Вертикальная лента коротких роликов, рекомендации и авторский контент.',tiles:[['▶','Лента Shorts','Вертикальный просмотр роликов'],['♥','Реакции и комментарии','Обсуждение и лайки'],['#','Хэштеги','Поиск роликов по темам'],['＋','Черновики','Подготовка публикаций']]},voice:{icon:'◖',title:'Голосовые комнаты',desc:'Голосовое общение и звонки в комнатах NEXUS.',tiles:[['🎙','Голосовые комнаты','Общение в реальном времени'],['📞','Звонки','Личные и групповые звонки'],['🔊','Аудиоканалы','Комнаты для серверов'],['🛡','Модерация','Управление участниками']]},servers:{icon:'◉',title:'Серверы NEXUS',desc:'Создавай свои пространства, приглашай людей и настраивай каналы.',tiles:[['▤','Текстовые каналы','Отдельные комнаты по темам'],['◖','Голосовые каналы','Общение голосом'],['♙','Роли и права','Настройка доступа'],['⚑','Форумы','Ветки и обсуждения']]},stories:{icon:'◌',title:'Истории',desc:'Короткие фото и видео, доступные подписчикам в течение 24 часов.',tiles:[['＋','Добавить историю','Фото или видео'],['◉','Просмотры','Список зрителей'],['✦','Отметки','Упоминания друзей'],['◷','Архив','Истории и воспоминания']]}}[view];const links={shorts:[['Открыть видео','videos'],['Найти авторов','people']],voice:[['Перейти в чаты','messages'],['Открыть серверы','servers']],servers:[['＋ Создать сервер','create-server'],['Найти серверы','clans']],stories:[['Открыть профиль','profile'],['Найти людей','people']]};$('viewRoot').innerHTML=`<section class="feature-hero"><div class="eyebrow">NEXUS / ${view.toUpperCase()}</div><div style="font-size:38px;margin-top:12px">${data.icon}</div><h2>${data.title}</h2><p>${data.desc}</p><div class="feature-actions">${links[view].map(x=>`<button class="secondary" data-feature-go="${x[1]}">${x[0]} →</button>`).join('')}</div></section><div class="feature-grid">${data.tiles.map(t=>`<article class="feature-tile"><span class="tile-icon">${t[0]}</span><b>${t[1]}</b><small>${t[2]}</small></article>`).join('')}</div><div class="status-note">Раздел уже добавлен в навигацию. Часть перечисленных возможностей пока представлена интерфейсом — для реальной работы потребуется отдельная серверная реализация.</div>`;document.querySelectorAll('[data-feature-go]').forEach(b=>b.onclick=()=>{if(b.dataset.featureGo==='create-server'){go('clans').then(()=>document.getElementById('createClan')?.click())}else go(b.dataset.featureGo)})}
function renderSettings(){const u=state.user;const saved=(k,def='')=>localStorage.getItem('nexusSetting:'+k)??def;
$('viewRoot').innerHTML=`<div class="column settings-page"><div class="section-title"><div><h2>Настройки</h2><p class="muted">Управление аккаунтом и приложением</p></div></div>
<div class="tabs settings-tabs"><button class="tab active" data-settings-tab="account">Аккаунт</button><button class="tab" data-settings-tab="chat">Настройки чата</button><button class="tab" data-settings-tab="privacy">Приватность и безопасность</button><button class="tab" data-settings-tab="alerts">Оповещения</button><button class="tab" data-settings-tab="storage">Данные и хранилище</button><button class="tab" data-settings-tab="devices">Устройства</button><button class="tab" data-settings-tab="language">Язык</button></div>
<section class="settings-pane" data-settings-pane="account"><div class="card"><h2>Профиль</h2><form id="settingsForm" style="margin-top:16px"><div class="field"><label>Имя в профиле</label><input id="setName" maxlength="40" value="${esc(u.displayName)}" required></div><div class="field"><label>Юзернейм</label><input id="setUsername" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" value="${esc(u.username)}" required><small>3–24 символа: латиница, цифры и _</small></div><div class="field"><label>Аватар профиля</label><input id="setAvatarFile" type="file" accept="image/png,image/jpeg,image/webp"><div id="avatarPreview" class="avatar-preview">${u.avatarUrl?`<img src="${esc(u.avatarUrl)}">`:''}</div><button type="button" class="secondary" id="confirmAvatar">Подтвердить фото</button></div><div class="field"><label>О себе</label><textarea id="setBio" maxlength="300" rows="3">${esc(u.bio||'')}</textarea></div><button class="primary" style="margin-top:18px">Сохранить профиль</button></form></div><div class="card"><h2>Учётная запись</h2><p class="muted">Почта: ${esc(u.email||'не указана')}</p><p class="muted">ID: ${u.id} · Регистрация: ${dt(u.createdAt)}</p><button id="deleteAccount" class="btn" style="color:var(--danger)">Удалить аккаунт</button></div></section>
<section class="settings-pane hidden" data-settings-pane="chat"><div class="card"><h2>Настройки чата</h2><p class="muted">Внешний вид переписок на этом устройстве.</p><div class="settings-choice-row"><span>Тема приложения</span><select id="appearanceTheme"><option value="dark">Тёмная</option><option value="light">Светлая</option></select></div><div class="settings-choice-row"><span>Стандартные обои</span><select id="chatWallpaper"><option value="violet">Фиолетовый градиент</option><option value="plain">Однотонные</option><option value="stars">Звёздный фон</option></select></div><div class="field"><label>Свои обои чата</label><input id="chatWallpaperFile" type="file" accept="image/*"><div id="wallpaperPreview" class="wallpaper-preview hidden"></div><div class="settings-actions"><button type="button" class="primary" id="confirmWallpaper" disabled>Подтвердить обои</button><button type="button" class="secondary" id="cancelWallpaper">Отмена</button></div><small class="muted">Сначала выбери файл, проверь предпросмотр и нажми «Подтвердить обои».</small></div><label class="settings-toggle"><input type="checkbox" id="sendEnter" ${saved('sendEnter','true')==='true'?'checked':''}> Отправлять сообщение клавишей Enter</label></div></section>
<section class="settings-pane hidden" data-settings-pane="privacy"><div class="card"><h2>Приватность и безопасность</h2><label class="settings-toggle"><input id="setPrivate" type="checkbox" ${u.private?'checked':''}> Приватный профиль</label><p class="muted">Для просмотра публикаций приватного профиля потребуется подписка, если сервер поддерживает это ограничение.</p><label class="settings-toggle"><input type="checkbox" id="onlineStatus" ${saved('onlineStatus','true')==='true'?'checked':''}> Показывать статус «в сети»</label><label class="settings-toggle"><input type="checkbox" id="readReceipts" ${saved('readReceipts','true')==='true'?'checked':''}> Отправлять отчёты о прочтении</label><label class="settings-toggle"><input type="checkbox" id="twoStep" ${saved('twoStep','false')==='true'?'checked':''}> Двухэтапная проверка (настройка интерфейса)</label><p class="tiny muted">Дополнительные серверные механизмы безопасности можно подключить отдельно.</p><button class="primary" id="savePrivacy">Сохранить приватность</button></div></section>
<section class="settings-pane hidden" data-settings-pane="alerts"><div class="card"><h2>Оповещения</h2><label class="settings-toggle"><input type="checkbox" id="notifyMessages" ${saved('notifyMessages','true')==='true'?'checked':''}> Новые сообщения</label><label class="settings-toggle"><input type="checkbox" id="notifyLikes" ${saved('notifyLikes','true')==='true'?'checked':''}> Лайки и комментарии</label><label class="settings-toggle"><input type="checkbox" id="notifyFollows" ${saved('notifyFollows','true')==='true'?'checked':''}> Новые подписчики</label><label class="settings-toggle"><input type="checkbox" id="notifyStories" ${saved('notifyStories','true')==='true'?'checked':''}> Истории</label><button class="primary" id="saveAlerts">Сохранить оповещения</button></div></section>
<section class="settings-pane hidden" data-settings-pane="storage"><div class="card"><h2>Данные и хранилище</h2><p class="muted">Управление локальными данными NEXUS в этом браузере.</p><div class="settings-choice-row"><span>Занято локальными данными</span><b id="storageSize">Подсчёт…</b></div><label class="settings-toggle"><input type="checkbox" id="autoMedia" ${saved('autoMedia','true')==='true'?'checked':''}> Автоматически загружать медиа в ленте</label><button class="secondary" id="clearDrafts">Очистить черновики</button><button class="secondary" id="clearCache">Очистить локальные настройки и кэш</button><p class="tiny muted">Очистка локальных данных не удаляет аккаунт и серверные сообщения.</p></div></section>
<section class="settings-pane hidden" data-settings-pane="devices"><div class="card"><h2>Устройства</h2><div class="notice-row"><div class="result-info"><b>Это устройство</b><small>${esc(navigator.userAgent.slice(0,150))}</small><small class="muted">Текущая сессия NEXUS</small></div><span class="tag">Активно</span></div><p class="muted">Управление другими сеансами появится после подключения серверного списка устройств.</p></div></section>
<section class="settings-pane hidden" data-settings-pane="language"><div class="card"><h2>Язык</h2><p class="muted">Выбери предпочтительный язык приложения.</p><div class="settings-choice-row"><span>Язык интерфейса</span><select id="appLanguage"><option value="ru">Русский</option><option value="uk">Українська</option><option value="en">English</option></select></div><p class="tiny muted">Выбор сохраняется на этом устройстве. Полный перевод всех экранов будет добавляться отдельно.</p></div></section>
${['owner','admin','moderator'].includes(u.role)?`<button class="settings-admin-link" id="openAdmin"><span><b>♛ Админ-панель</b><small>Управление пользователями, жалобами и платформой</small></span><span>Открыть →</span></button>`:''}</div>`;
const theme=localStorage.getItem('nexusTheme')||'dark';$('appearanceTheme').value=theme;$('chatWallpaper').value=localStorage.getItem('nexusChatWallpaper')||'violet';$('appLanguage').value=saved('language','ru');
document.querySelectorAll('[data-settings-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-settings-pane]').forEach(x=>x.classList.toggle('hidden',x.dataset.settingsPane!==b.dataset.settingsTab))});
$('appearanceTheme').onchange=()=>{const light=$('appearanceTheme').value==='light';document.body.classList.toggle('light',light);document.documentElement.dataset.theme=light?'light':'dark';localStorage.setItem('nexusTheme',light?'light':'dark')};$('chatWallpaper').onchange=()=>{localStorage.setItem('nexusChatWallpaper',$('chatWallpaper').value);localStorage.removeItem('nexusChatWallpaperImage');document.body.dataset.chatWallpaper=$('chatWallpaper').value;document.body.style.setProperty('--chat-wallpaper','')};let wallpaperFile=null;$('chatWallpaperFile').onchange=()=>{wallpaperFile=$('chatWallpaperFile').files[0]||null;const preview=$('wallpaperPreview');if(wallpaperFile){if(!wallpaperFile.type.startsWith('image/')){wallpaperFile=null;toast('Выбери файл изображения');return}preview.style.backgroundImage=`url("${URL.createObjectURL(wallpaperFile)}")`;preview.classList.remove('hidden');$('confirmWallpaper').disabled=false}else{preview.classList.add('hidden');$('confirmWallpaper').disabled=true}};$('confirmWallpaper').onclick=async()=>{if(!wallpaperFile)return;const btn=$('confirmWallpaper');btn.disabled=true;try{const fd=new FormData();fd.append('file',wallpaperFile);const up=await api('/api/upload',{method:'POST',body:fd});if(up.type!=='image')throw new Error('Для обоев выбери изображение');localStorage.setItem('nexusChatWallpaperImage',up.url);localStorage.setItem('nexusChatWallpaper','custom');document.body.style.setProperty('--chat-wallpaper',`url("${up.url}")`);document.body.dataset.chatWallpaper='custom';toast('Обои чата применены')}catch(e){toast(e.message);btn.disabled=false}};$('cancelWallpaper').onclick=()=>{wallpaperFile=null;$('chatWallpaperFile').value='';$('wallpaperPreview').classList.add('hidden');$('confirmWallpaper').disabled=true};
$('setAvatarFile').onchange=()=>{const f=$('setAvatarFile').files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('avatarPreview').innerHTML=`<img src="${r.result}">`};r.readAsDataURL(f)};$('confirmAvatar').onclick=async()=>{const f=$('setAvatarFile').files[0];if(!f){toast('Сначала выбери фото');return}try{const fd=new FormData();fd.append('file',f);const up=await api('/api/upload',{method:'POST',body:fd});if(up.type!=='image')throw new Error('Для аватара выбери изображение');state.pendingAvatarUrl=up.url;$('avatarPreview').innerHTML=`<img src="${up.url}">`;toast('Фото подтверждено. Нажми «Сохранить профиль»')}catch(e){toast(e.message)}};
$('settingsForm').onsubmit=async e=>{e.preventDefault();try{let avatarUrl=state.pendingAvatarUrl||u.avatarUrl||null;const file=$('setAvatarFile').files[0];if(file&&!state.pendingAvatarUrl){const fd=new FormData();fd.append('file',file);const up=await api('/api/upload',{method:'POST',body:fd});if(up.type!=='image')throw new Error('Для аватара выбери изображение');avatarUrl=up.url}const d=await api('/api/me',{method:'PATCH',body:JSON.stringify({displayName:$('setName').value,username:$('setUsername').value,avatar:'',avatarUrl,bio:$('setBio').value})});state.user=d.user;state.pendingAvatarUrl=null;$('miniName').textContent=state.user.displayName;$('miniHandle').textContent='@'+state.user.username;$('miniAvatar').innerHTML=state.user.avatarUrl?`<img src="${esc(state.user.avatarUrl)}">`:'';$('topAvatar').innerHTML=state.user.avatarUrl?`<img src="${esc(state.user.avatarUrl)}">`:'';go('settings');toast('Профиль сохранён')}catch(e){toast(e.message)}};
const saveLocal=(keys)=>keys.forEach(k=>{const el=$(k);if(el)localStorage.setItem('nexusSetting:'+k,String(el.type==='checkbox'?el.checked:el.value))});$('savePrivacy').onclick=async()=>{try{const d=await api('/api/me',{method:'PATCH',body:JSON.stringify({private:$('setPrivate').checked})});state.user=d.user;saveLocal(['onlineStatus','readReceipts','twoStep']);toast('Приватность сохранена')}catch(e){toast(e.message)}};$('saveAlerts').onclick=()=>{saveLocal(['notifyMessages','notifyLikes','notifyFollows','notifyStories']);toast('Настройки оповещений сохранены')};$('sendEnter').onchange=()=>saveLocal(['sendEnter']);$('autoMedia').onchange=()=>saveLocal(['autoMedia']);$('appLanguage').onchange=()=>{localStorage.setItem('nexusSetting:language',$('appLanguage').value);toast('Язык сохранён. Полный перевод интерфейса будет добавлен отдельно')};
const bytes=new Blob([JSON.stringify(localStorage)]).size;$('storageSize').textContent=(bytes/1024).toFixed(1)+' КБ';$('clearDrafts').onclick=()=>{if(confirm('Удалить все черновики на этом устройстве?')){localStorage.removeItem('nexusDrafts:'+state.user.id);toast('Черновики очищены')}};$('clearCache').onclick=()=>{if(confirm('Очистить локальные настройки NEXUS?')){Object.keys(localStorage).filter(k=>k.startsWith('nexusSetting:')).forEach(k=>localStorage.removeItem(k));toast('Локальные настройки очищены');renderSettings()}};
document.body.dataset.chatWallpaper=localStorage.getItem('nexusChatWallpaper')||'violet';if($('openAdmin'))$('openAdmin').onclick=()=>go('admin');$('deleteAccount').onclick=async()=>{if(confirm('Точно удалить аккаунт и связанные данные?')){await api('/api/me',{method:'DELETE'});location.reload()}}}

async function renderAdmin(){const [d,u,a]=await Promise.all([api('/api/admin/stats'),api('/api/admin/users'),api('/api/admin/audit')]);const owner=state.user.role==='owner';$('viewRoot').innerHTML=`<div class="section-title"><div><h2>Админ-панель NEXUS</h2><p class="muted">${owner?'Главный администратор':'Управление платформой'}</p></div></div><div class="grid-cards">${[['Пользователи',d.stats.users],['Публикации',d.stats.posts],['Кланы',d.stats.clans],['Открытые жалобы',d.stats.reports]].map(x=>`<div class="card"><small class="muted">${x[0]}</small><h2 style="font-size:32px;margin-top:10px">${x[1]}</h2></div>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Пользователи</h2>${u.users.map(x=>`<div class="notice-row"><div class="result-info"><b>@${esc(x.username)} ${x.role==='owner'?'♛':''}</b><small>${esc(x.email)} · ${esc(x.role)} · ID ${x.id} ${x.is_banned?'· ЗАБЛОКИРОВАН':''}</small></div>${owner&&x.role!=='owner'?`<select data-role-id="${x.id}"><option value="user" ${x.role==='user'?'selected':''}>user</option><option value="moderator" ${x.role==='moderator'?'selected':''}>moderator</option><option value="admin" ${x.role==='admin'?'selected':''}>admin</option></select><button class="secondary small-btn" data-delete-user="${x.id}">Удалить</button>`:''}${x.role!=='owner'&&!x.is_banned?`<button class="secondary small-btn" data-ban="${x.id}">Блокировать</button>`:x.is_banned?`<button class="secondary small-btn" data-unban="${x.id}">Разблокировать</button>`:''}</div>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Жалобы</h2>${d.reports.map(r=>`<div class="notice-row"><div class="result-info"><b>Жалоба #${r.id}</b><small>От @${esc(r.reporter)} · ${dt(r.created_at)}</small><p>${esc(r.reason)}</p></div><button class="secondary small-btn" data-remove-post="${r.post_id||''}">Удалить пост</button></div>`).join('')||'<div class="empty-state">Жалоб пока нет.</div>'}</div><div class="card" style="margin-top:18px"><h2>Журнал действий</h2>${a.entries.map(x=>`<div class="notice-row"><div class="result-info"><b>${esc(x.action)}</b><small>${esc(x.actor_username||'система')} → ${esc(x.target_username||'нет цели')} · ${dt(x.created_at)}</small></div></div>`).join('')||'<p class="muted">Действий пока нет.</p>'}</div>`;document.querySelectorAll('[data-role-id]').forEach(el=>el.onchange=async()=>{try{await api('/api/admin/users/'+el.dataset.roleId+'/role',{method:'POST',body:JSON.stringify({role:el.value})});toast('Роль изменена')}catch(e){toast(e.message);renderAdmin()}});document.querySelectorAll('[data-ban]').forEach(b=>b.onclick=async()=>{const reason=prompt('Причина блокировки','Нарушение правил')||'Нарушение правил';await api('/api/admin/users/'+b.dataset.ban+'/ban',{method:'POST',body:JSON.stringify({reason})});renderAdmin()});document.querySelectorAll('[data-unban]').forEach(b=>b.onclick=async()=>{await api('/api/admin/users/'+b.dataset.unban+'/unban',{method:'POST',body:'{}'});renderAdmin()});document.querySelectorAll('[data-delete-user]').forEach(b=>b.onclick=async()=>{if(confirm('Удалить аккаунт без возможности восстановления?')){await api('/api/admin/users/'+b.dataset.deleteUser,{method:'DELETE'});renderAdmin()}});document.querySelectorAll('[data-remove-post]').forEach(b=>b.onclick=async()=>{if(b.dataset.removePost){await api('/api/posts/'+b.dataset.removePost,{method:'DELETE'});toast('Публикация удалена');renderAdmin()}})}
async function renderChats(){const d=await api('/api/chats');state.chats=d.chats;const meta=JSON.parse(localStorage.getItem('nexusChatMeta')||'{}');const filter=state.chatFilter||'all';const sorted=[...d.chats].filter(c=>filter==='archive'?meta[c.id]?.archived:!meta[c.id]?.archived).sort((a,b)=>Number(!!meta[b.id]?.pinned)-Number(!!meta[a.id]?.pinned));$('viewRoot').innerHTML=`<div class="telegram-shell"><aside class="chat-sidebar card"><div class="chat-sidebar-head"><div><h2>Сообщения</h2><small class="muted">Твои диалоги</small></div></div><div class="chat-filters"><button class="tab ${filter==='all'?'active':''}" data-chat-filter="all">Все</button><button class="tab ${filter==='archive'?'active':''}" data-chat-filter="archive">Архив</button></div><div class="chat-list">${sorted.map(c=>`<div class="chat-row ${state.activeChat&&String(state.activeChat.id)===String(c.id)?'selected':''}"><button class="chat-open" data-open-chat="${c.id}"><span class="profile-avatar-link" data-user="${esc(c.user.username)}">${avatar(c.user.avatar,c.user.avatarUrl)}</span><span class="result-info"><b class="click-user" data-user="${esc(c.user.username)}">${esc(c.user.displayName)} ${meta[c.id]?.pinned?'📌':''}</b><small>@${esc(c.user.username)} · ${esc(c.lastMessage||'Начните общение')}</small></span></button><div class="chat-tools"><button title="${meta[c.id]?.pinned?'Открепить':'Закрепить'}" data-pin-chat="${c.id}">${meta[c.id]?.pinned?'📌':'⌖'}</button><button title="${meta[c.id]?.archived?'Вернуть из архива':'В архив'}" data-archive-chat="${c.id}">${meta[c.id]?.archived?'↩':'▱'}</button></div></div>`).join('')||'<div class="empty-state">Здесь пока пусто. Нажми «＋», чтобы найти собеседника.</div>'}</div></aside><section class="chat-conversation card" id="chatPane"><div class="chat-placeholder"><div class="logo big-logo">N</div><h2>NEXUS Чаты</h2><p class="muted">Выбери диалог слева или начни новый.</p></div><div id="chatBox" class="hidden chat-box"><div class="chat-conversation-head"><h2 id="chatTitle">Чат</h2><span class="muted">NEXUS</span></div><div id="messagesList" class="messages-list"></div><form id="sendMessage" class="comment-row chat-compose"><input id="messageText" class="comment-input" maxlength="4000" placeholder="Сообщение…" required><button class="primary">➤</button></form></div></section></div>`;document.querySelectorAll('.chat-list [data-user]').forEach(el=>el.onclick=e=>{e.stopPropagation();renderProfile(el.dataset.user,false)});document.querySelectorAll('[data-open-chat]').forEach(b=>b.onclick=()=>openChat(b.dataset.openChat));document.querySelectorAll('[data-chat-filter]').forEach(b=>b.onclick=()=>{state.chatFilter=b.dataset.chatFilter;renderChats()});document.querySelectorAll('[data-pin-chat]').forEach(b=>b.onclick=()=>{const m=JSON.parse(localStorage.getItem('nexusChatMeta')||'{}');m[b.dataset.pinChat]=m[b.dataset.pinChat]||{};m[b.dataset.pinChat].pinned=!m[b.dataset.pinChat].pinned;localStorage.setItem('nexusChatMeta',JSON.stringify(m));renderChats()});document.querySelectorAll('[data-archive-chat]').forEach(b=>b.onclick=()=>{const m=JSON.parse(localStorage.getItem('nexusChatMeta')||'{}');m[b.dataset.archiveChat]=m[b.dataset.archiveChat]||{};m[b.dataset.archiveChat].archived=!m[b.dataset.archiveChat].archived;localStorage.setItem('nexusChatMeta',JSON.stringify(m));if(state.activeChat&&String(state.activeChat.id)===String(b.dataset.archiveChat))state.activeChat=null;renderChats()});if(state.activeChat&&d.chats.some(c=>String(c.id)===String(state.activeChat.id)))openChat(state.activeChat.id);} 
async function openChat(id){const c=state.chats.find(c=>String(c.id)===String(id));if(!c)return;state.activeChat=c;document.querySelectorAll('.chat-row').forEach(r=>r.classList.toggle('selected',!!r.querySelector(`[data-open-chat="${id}"]`)));$('chatBox').classList.remove('hidden');const ph=document.querySelector('.chat-placeholder');if(ph)ph.classList.add('hidden');$('chatTitle').textContent=c.user.displayName+' (@'+c.user.username+')';if(state.socket)state.socket.emit('chat:join',{conversationId:id});await renderMessages();$('sendMessage').onsubmit=e=>{e.preventDefault();const body=$('messageText').value.trim();if(!body)return;if(!state.socket||!state.socket.connected){$('messagesList').insertAdjacentHTML('beforeend',`<div class="message-line mine"><div class="message-stack"><b class="message-sender">${esc(state.user.displayName)}</b><div class="message-bubble mine failed"><p>${esc(body)}</p><small>✕ Не отправлено</small></div></div></div>`);return}state.socket.emit('chat:send',{conversationId:id,body},r=>{if(r?.error){const list=$('messagesList');list.insertAdjacentHTML('beforeend',`<div class="message-line mine"><div class="message-stack"><b class="message-sender">${esc(state.user.displayName)}</b><div class="message-bubble mine failed"><p>${esc(body)}</p><small>✕ Не отправлено</small></div></div></div>`);toast(r.error)}else $('messageText').value=''})}}
async function renderMessages(){if(!state.activeChat)return;try{const d=await api('/api/chats/'+state.activeChat.id+'/messages');$('messagesList').innerHTML=d.messages.map(m=>`<div class="message-line ${String(m.senderId)===String(state.user.id)?'mine':'theirs'}"><button class="profile-avatar-link" data-user="${esc(m.username||'')}">${avatar(m.avatar,m.avatarUrl)}</button><div class="message-stack"><b class="message-sender click-user" data-user="${esc(m.username||'')}">${esc(m.displayName||'Пользователь')}</b><div class="message-bubble ${String(m.senderId)===String(state.user.id)?'mine':'theirs'}"><p>${esc(m.body)}</p><small>${dt(m.createdAt)} ${String(m.senderId)===String(state.user.id)?(m.readAt?'✓✓':'✓') : ''}</small></div></div></div>`).join('')||'<div class="empty-state">Начни переписку первым.</div>';document.querySelectorAll('#messagesList [data-user]').forEach(el=>el.onclick=()=>{if(el.dataset.user)renderProfile(el.dataset.user,false)})}catch(e){toast(e.message)}}
async function init(){try{const d=await api('/api/me');state.user=d.user;afterLogin();loadNotificationCount()}catch{$('authScreen').classList.remove('hidden')}}
init();
})();